-- +goose Up

-- Per-tenant secret used to verify inbound webhook signatures -- distinct
-- from consumer_secret_encrypted (that one authenticates OUR outbound REST
-- calls to the store; this one verifies THEIR inbound webhook calls to us).
-- WooCommerce's own signing-secret derivation when none is explicitly
-- configured is undocumented closely enough to reimplement blind, so this
-- app always requires an explicit secret: generated by CommerceOS when the
-- merchant enables webhooks, then pasted into the store's webhook admin UI
-- as its "secret" field. Empty string means webhooks aren't configured yet
-- for that connection -- ReceiveWebhookUseCase treats that the same as
-- "provider not implemented" (no secret to verify against, so no request
-- can ever be trusted).
ALTER TABLE integration_connections ADD COLUMN webhook_secret_encrypted TEXT NOT NULL DEFAULT '';

-- Landing table for a webhook whose payload could NOT be published to
-- COMMERCEOS_WEBHOOKS after ReceiveWebhookUseCase's bounded in-request
-- retries (see application/webhooks.ReceiveWebhookUseCase) -- the
-- deliberate safety net for "don't miss a request" when JetStream itself
-- is unreachable. Rare by design: the hot path stays DB-free on the
-- success path, this table only ever gets a row on publish failure.
CREATE TABLE webhook_fallback_events (
    id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id    UUID        NOT NULL,
    provider     TEXT        NOT NULL,
    event_id     TEXT        NOT NULL,
    payload      JSONB       NOT NULL,
    headers      JSONB       NOT NULL DEFAULT '{}',
    status       TEXT        NOT NULL DEFAULT 'pending_republish',
    received_at  TIMESTAMPTZ NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT webhook_fallback_events_status_check CHECK (status IN ('pending_republish', 'republished', 'abandoned')),
    UNIQUE (tenant_id, provider, event_id)
);

CREATE INDEX webhook_fallback_events_tenant_id_idx ON webhook_fallback_events (tenant_id);
CREATE INDEX webhook_fallback_events_status_idx ON webhook_fallback_events (status);

ALTER TABLE webhook_fallback_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE webhook_fallback_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON webhook_fallback_events
    USING (current_setting('app.current_tenant', true) = 'bypass_rls'
        OR tenant_id = NULLIF(current_setting('app.current_tenant', true), 'bypass_rls')::uuid);

-- Cold-path landing record: one row per webhook the worker (cmd/webhook-
-- processor) has successfully consumed off COMMERCEOS_WEBHOOKS and
-- persisted -- the actual "process later" destination. Business-rule
-- dispatch per provider/topic is intentionally out of scope for this pass;
-- this table is the durable, queryable proof the event was received and
-- accepted for processing.
CREATE TABLE webhook_events (
    id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id    UUID        NOT NULL,
    provider     TEXT        NOT NULL,
    event_id     TEXT        NOT NULL,
    topic        TEXT        NOT NULL DEFAULT '',
    payload      JSONB       NOT NULL,
    received_at  TIMESTAMPTZ NOT NULL,
    processed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (tenant_id, provider, event_id)
);

CREATE INDEX webhook_events_tenant_id_idx ON webhook_events (tenant_id);

ALTER TABLE webhook_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE webhook_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON webhook_events
    USING (current_setting('app.current_tenant', true) = 'bypass_rls'
        OR tenant_id = NULLIF(current_setting('app.current_tenant', true), 'bypass_rls')::uuid);

-- +goose Down
DROP TABLE webhook_events;
DROP TABLE webhook_fallback_events;
ALTER TABLE integration_connections DROP COLUMN webhook_secret_encrypted;
